const cfg = {};
for (const item of $input.all()) {
  const row = item.json || {};
  if (row.config_key) cfg[row.config_key] = String(row.config_value ?? '');
}
return [{ json: cfg }];

function unwrapMessage(msg) {
  if (!msg || typeof msg !== 'object') return {};
  const wrappers = ['ephemeralMessage', 'viewOnceMessage', 'viewOnceMessageV2', 'viewOnceMessageV2Extension', 'documentWithCaptionMessage', 'editedMessage'];
  for (const w of wrappers) {
    if (msg[w] && msg[w].message) return unwrapMessage(msg[w].message);
  }
  return msg;
}

const root = $('Webhook Evolution').first().json || {};
const payload = root.body && root.body.data ? root.body : root;
const event = String(payload.event || '');
if (event && event !== 'messages.upsert') {
  return [];
}
const data = payload.data || {};
const key = data.key || {};
const remoteJid = String(key.remoteJid || '');
if (!remoteJid || remoteJid.endsWith('@g.us') || remoteJid.includes('status@broadcast') || remoteJid.endsWith('@broadcast')) {
  return [];
}
const alt = String(key.remoteJidAlt || '');
const jidForPhone = alt.includes('@s.whatsapp.net') ? alt : remoteJid;
const phone = jidForPhone.replace(/[^0-9]/g, '');
if (!phone) {
  return [];
}

const digits = (value) => String(value || '').replace(/[^0-9]/g, '');
const samePhone = (a, b) => {
  if (!a || !b) return false;
  if (a === b) return true;
  return a.length >= 10 && b.length >= 10 && a.slice(-10) === b.slice(-10);
};
const senderPhone = digits(payload.sender || data.sender || '');
const selfChat = Boolean(key.fromMe) && senderPhone && (
  samePhone(senderPhone, phone) ||
  samePhone(senderPhone, digits(remoteJid)) ||
  samePhone(senderPhone, digits(alt))
);
const msg = unwrapMessage(data.message || {});
const declared = String(data.messageType || '');
const mimeOf = (obj) => String((obj && obj.mimetype) || '');

let contentType = 'unknown';
if (msg.extendedTextMessage || msg.conversation || declared === 'conversation' || declared === 'extendedTextMessage') {
  contentType = 'text';
}
if (msg.imageMessage || declared === 'imageMessage' || mimeOf(msg.documentMessage).startsWith('image/')) {
  contentType = 'image';
}
if (msg.videoMessage || msg.ptvMessage || declared === 'videoMessage' || declared === 'ptvMessage') {
  contentType = 'video';
}
if (msg.audioMessage || declared === 'audioMessage') {
  contentType = 'audio';
}
if (msg.stickerMessage || declared === 'stickerMessage') {
  contentType = 'sticker';
}
if ((msg.documentMessage || declared === 'documentMessage') && contentType === 'unknown') {
  contentType = 'document';
}

const caption = [
  (msg.extendedTextMessage && msg.extendedTextMessage.text) || '',
  msg.conversation || '',
  (msg.imageMessage && msg.imageMessage.caption) || '',
  (msg.videoMessage && msg.videoMessage.caption) || '',
  (msg.documentMessage && (msg.documentMessage.caption || msg.documentMessage.fileName)) || '',
].join('').trim();

const labels = {
  image: '[Imagen enviada]',
  video: '[Video enviado]',
  audio: '[Audio enviado]',
  sticker: '[Sticker enviado]',
  document: '[Documento enviado]',
};
let content = caption;
if (labels[contentType]) {
  content = caption ? `${labels[contentType]} ${caption}` : labels[contentType];
}

const ts = data.messageTimestamp;
let occurredAt;
if (typeof ts === 'number') {
  occurredAt = DateTime.fromSeconds(ts).toISO();
} else if (ts && typeof ts.low === 'number') {
  occurredAt = DateTime.fromSeconds(ts.low).toISO();
} else {
  occurredAt = DateTime.now().setZone('America/Caracas').toISO();
}

return [{
  json: {
    whatsapp_jid: remoteJid,
    phone,
    display_name: String(data.pushName || ''),
    from_me: Boolean(key.fromMe),
    self_chat: selfChat,
    message_id: String(key.id || `${remoteJid}-${occurredAt}`),
    content_type: contentType,
    body: content,
    occurred_at: occurredAt,
    evo_server_url: String(payload.server_url || '').replace(/\/$/, ''),
    evo_instance: String(payload.instance || ''),
    evo_apikey: String(payload.apikey || ''),
  },
}];

