SELECT EXISTS (
  SELECT 1
  FROM team_phones t
  WHERE t.active
    AND t.skip_followup
    AND (
      t.phone = $1
      OR right(t.phone, 10) = right(regexp_replace($1::text, '[^0-9]', '', 'g'), 10)
    )
) AS skip_score;

