const nested = raw.data && typeof raw.data === 'object' ? raw.data : {};
let base64 = String(raw.base64 || raw.base64Data || nested.base64 || '');
base64 = base64.replace(/^data:image\/[a-zA-Z0-9.+-]+;base64,/, '');
