}
return [{ json: { media_ok: true, base64, mimetype } }];

const parsed = $input.first().json || {};
const prep = $('Preparar update').first().json || {};
const norm = $('Normalizar').first().json || {};
const extra = parsed.additional_kwargs || parsed.additionalKwargs || {};
let data = {};
let raw = '';
if (parsed.tipo || parsed.senal_embudo) {
