  if (raw && typeof raw === 'object') raw = JSON.stringify(raw);
  raw = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();
  if (!raw.startsWith('{')) {
    const dumped = JSON.stringify(parsed);
    const match = dumped.match(/\{[^{}]*"tipo"\s*:\s*"[^"]+"[^{}]*\}/);
    if (match) raw = match[0];
