const body = mediaOk
  ? [`[Imagen] tipo=${tipo} senal=${senal}: ${resumen || 'sin resumen'}`, texto_visible ? `Texto: ${texto_visible}` : '', caption ? `Caption: ${caption}` : ''].filter(Boolean).join(' ')
  : (caption ? `[Imagen no disponible] ${caption}` : '[Imagen no disponible]');
