const raw = $input.first().json || {};
const prep = $('Preparar update').first().json || {};
const norm = $('Normalizar').first().json || {};
const doc = raw.document || {};
let text = String(doc.text_content || doc.md_content || '').replace(/\s+/g, ' ').trim();
const md = String(doc.md_content || '').trim();
const ok = Boolean(text) && String(raw.status || '').toLowerCase() !== 'failure';

// Primera hoja: cortar políticas / página 2
const cutRe = /\b(NOTA\s*:|IMPORTANTE\s*:|NUESTRA\s+POL[IÍ]TIC|POL[IÍ]TICAS\s+anex|Favor presentar este documento|<!--\s*page\s*break|formfeed)/i;
const cutAt = text.search(cutRe);
if (cutAt > 80) text = text.slice(0, cutAt).trim();
let mdFirst = md;
const mdCut = mdFirst.search(cutRe);
if (mdCut > 80) mdFirst = mdFirst.slice(0, mdCut).trim();
const src = `${mdFirst}\n${text}`;

const pick = (re) => {
  const m = src.match(re);
  return m ? String(m[1] || m[2] || '').replace(/\s+/g, ' ').trim() : '';
};
const looksLikeRoom = (s) => /matrimonial|individual|suite|est[aá]ndar|doble|triple|\d+\s/i.test(s)
  && !/debe pagar|acuerdo al caso|pol[ií]tica/i.test(s);

let huesped = pick(/Ciudadano\(a\):\s*([A-ZÁÉÍÓÚÑÜ][A-ZÁÉÍÓÚÑÜa-záéíóúñü\s.'-]{2,80}?)(?=\s+[VEP]-|\s+PAS-|\s+Presente|\s+RIF:|$)/i)
  || pick(/hu[eé]sped(?:es)?\s*[:\-]\s*([^\n|]+)/i);
