const checkin = pick(/Check\s*In\s*:[^F]{0,40}Fecha\s*:\s*([0-9]{1,2}[\/\-.][0-9]{1,2}[\/\-.][0-9]{2,4})/i)
  || pick(/check[\s\-]?in\s*[:\-]\s*([0-9]{1,2}[\/\-.][0-9]{1,2}[\/\-.][0-9]{2,4})/i);

const checkout = pick(/Check\s*Out\s*:[^F]{0,40}Fecha\s*:\s*([0-9]{1,2}[\/\-.][0-9]{1,2}[\/\-.][0-9]{2,4})/i)
  || pick(/check[\s\-]?out\s*[:\-]\s*([0-9]{1,2}[\/\-.][0-9]{1,2}[\/\-.][0-9]{2,4})/i);

let habitacion = pick(/Tipo\(s\)\s+de\s+Habitaci[oó]n(?:\(es\)|es)?\s*:\s*([^\-|]+?)(?=\s*-\s*Destino|\s*Monto|\s*Plan|\s*$)/i)
  || pick(/Habitaci[oó]n(?:es)?\s*:\s*([A-Z0-9ÁÉÍÓÚÑÜ][A-Z0-9ÁÉÍÓÚÑÜa-záéíóúñü\s.]{2,60})/i);
if (habitacion && !looksLikeRoom(habitacion)) habitacion = '';

const plan = pick(/Plan\s*:\s*([^-|]+?)(?=\s*-\s*PAX|\s*-\s*Duraci|\s*$)/i);
const pax = pick(/PAX\.?\s*(\d+)/i);
const noches = pick(/Duraci[oó]n\s*:\s*([^-\n|]+?)(?=\s*-\s*Check|\s*$)/i);
const monto = pick(/Monto Total(?: de Hospedaje)?\s*:\s*(€?\s*[\d.,]+)/i);
const pendiente = pick(/Monto Pendiente(?: a Pagar)?\s*:\s*(€?\s*[\d.,]+)/i);
const formaPago = pick(/\|?\s*(TARJETA\s+INTERNACIONAL|PAGO\s+M[OÓ]VIL|TRANSFERENCIA|ZELLE|EFECTIVO|DEP[OÓ]SITO)[^|]{0,40}/i)
  || pick(/Forma de pago[^A-Z]{0,20}([A-ZÁÉÍÓÚÑÜ][A-ZÁÉÍÓÚÑÜ\s]{3,40})/i);
const cuentaPago = pick(/\b(EN EL HOTEL)\b/i);
const destino = pick(/Destino\s*:\s*([^-|]+?)(?=\s*Monto|\s*$)/i);
const asesora = pick(/\b(EVELIN\s+YARZA|DARWIN\s+BRET|[A-ZÁÉÍÓÚÑÜ]{3,}\s+[A-ZÁÉÍÓÚÑÜ]{3,})\s+EJECUTIVA/i)
  || pick(/EJECUTIVA DE VENTAS[^A-Z]{0,5}([A-ZÁÉÍÓÚÑÜ\s]{5,40})/i);
const telAsesora = pick(/\b(04\d{2}\s?\d{3}\s?\d{4})\b/);
const emitido = pick(/Tucacas,?\s*([0-9]{1,2}\s+de\s+[A-Za-zÁÉÍÓÚáéíóú]+\s+de\s+[0-9]{4})/i);
