const fields = {
  huesped: huesped || null,
  cedula: cedula || null,
  checkin: checkin || null,
  checkout: checkout || null,
  noches: noches || null,
  habitacion: habitacion || null,
  plan: plan || null,
  pax: pax || null,
  monto: monto || null,
  pendiente: pendiente || null,
  forma_pago: [formaPago, cuentaPago].filter(Boolean).join(' ').trim() || null,
  destino: destino || null,
  asesora: (asesora || '').replace(/\s+EJECUTIVA.*/i, '').trim() || null,
  tel_asesora: telAsesora || null,
  emitido: emitido || null,
  archivo: caption || null,
