const bits = [];
if (fields.huesped) bits.push(`Huésped: ${fields.huesped}`);
if (fields.cedula) bits.push(`Cédula: ${fields.cedula}`);
if (fields.checkin) bits.push(`Check-in: ${fields.checkin}`);
if (fields.checkout) bits.push(`Check-out: ${fields.checkout}`);
if (fields.noches) bits.push(`Estancia: ${fields.noches}`);
if (fields.habitacion) bits.push(`Habitación: ${fields.habitacion}`);
if (fields.plan) bits.push(`Plan: ${fields.plan}`);
if (fields.pax) bits.push(`PAX: ${fields.pax}`);
if (fields.monto) bits.push(`Monto: ${fields.monto}`);
if (fields.pendiente) bits.push(`Pendiente: ${fields.pendiente}`);
if (fields.forma_pago) bits.push(`Pago: ${fields.forma_pago}`);
if (fields.destino) bits.push(`Destino: ${fields.destino}`);
if (fields.asesora) bits.push(`Asesora: ${fields.asesora}`);
if (fields.tel_asesora) bits.push(`Tel: ${fields.tel_asesora}`);
if (fields.emitido) bits.push(`Emitido: ${fields.emitido}`);

const analysis = ok
  ? JSON.stringify({ tipo: 'certificado_reserva', resumen_primera_hoja: true, ...fields })
  : null;

const body = ok
  ? (bits.length
      ? `[Certificado] ${bits.join(' | ')}`
      : `[Certificado] ${text.slice(0, 500)}`)
  : (caption ? `[Documento no leido] ${caption}` : '[Documento no leido]');

return [{
  json: {
    message_id: prep.message_id,
    lead_id: prep.lead_id,
    ok,
    media_analysis: analysis,
    media_signal: ok ? 'reserva' : 'ninguna',
    body,
    huesped: fields.huesped || '',
    checkin: fields.checkin || '',
    checkout: fields.checkout || '',
  },
}];
